html:
{%- from "adeel_traders/templates/print/base_80mm.html" import styles, header, line -%}
{{ styles() }}
<div class="at-r">
{{ header() }}
<div class="c title">{{ "Stock moved" if doc.stock_entry_type == "Material Transfer" else doc.stock_entry_type }}</div>
<div class="c small">{{ doc.name }}</div>
<div class="c small">{{ frappe.format(doc.posting_date, {"fieldtype": "Date"}) }} {{ (doc.posting_time | string)[:5] if doc.posting_time else "" }}</div>
<hr>
{%- set first = doc["items"][0] if doc["items"] else None %}
{% if first and first.s_warehouse %}{{ line("From", first.s_warehouse.rsplit(" - ", 1)[0]) }}{% endif %}
{% if first and first.t_warehouse %}{{ line("To", first.t_warehouse.rsplit(" - ", 1)[0]) }}{% endif %}
{% if doc.get("at_adjustment_reason") %}{{ line("Reason", doc.at_adjustment_reason) }}{% endif %}
<hr>
<table>
	{%- for row in doc["items"] %}
	<tr><td>{{ row.item_name }}<br><span class="small">{{ row.item_code }}{% if row.batch_no %} · {{ row.batch_no }}{% endif %}</span></td>
	<td class="num">{{ frappe.utils.fmt_money(row.qty, precision=0) }} {{ row.uom }}</td></tr>
	{%- endfor %}
</table>
<hr>
{{ line("Total pieces", frappe.utils.fmt_money(doc["items"] | sum(attribute="transfer_qty"), precision=0)) }}
<table><tr><td style="width:50%;padding-right:8px"><div class="sign">Given by</div></td><td><div class="sign">Received by</div></td></tr></table>
</div>
